import{_ as o,o as t,c as d,a2 as a}from"./chunks/framework.BN2sqjC1.js";const p=JSON.parse('{"title":"Riferimento di configurazione","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/configurazione.md","filePath":"admin-guide/configurazione.md"}'),i={name:"admin-guide/configurazione.md"};function c(r,e,n,l,s,u){return t(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="riferimento-di-configurazione" tabindex="-1">Riferimento di configurazione <a class="header-anchor" href="#riferimento-di-configurazione" aria-label="Permalink to &quot;Riferimento di configurazione&quot;">​</a></h1><p>Il binario <code>clarae-cloud</code> si configura <strong>solo con variabili d&#39;ambiente</strong> (12-factor) e con il flag <code>--role</code>. Questa pagina elenca ogni variabile letta da <code>services/cloud/internal/config/config.go</code>. Un test (<code>TestEveryEnvVarIsDocumented</code> in <code>services/cloud/internal/config</code>) fallisce se una variabile del codice non compare in questa tabella: aggiungere una variabile al codice richiede di documentarla qui.</p><h2 id="ruolo-del-processo" tabindex="-1">Ruolo del processo <a class="header-anchor" href="#ruolo-del-processo" aria-label="Permalink to &quot;Ruolo del processo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Flag</th><th>Effetto</th></tr></thead><tbody><tr><td><code>--role=all</code></td><td>API HTTP + gRPC e worker nello stesso processo (default dell&#39;immagine; sviluppo e piccole istanze).</td></tr><tr><td><code>--role=api</code></td><td>Solo API HTTP, gRPC/SSE e Web UI.</td></tr><tr><td><code>--role=worker</code></td><td>Solo lavori in background (GC blob, retention, compattazione, export). Non richiede <code>OIDC_*</code>. Apre solo un listener interno (<code>METRICS_LISTEN_ADDR</code>) con <code>/metrics</code>, <code>/healthz</code> e <code>/readyz</code>.</td></tr></tbody></table><p>I job usano un advisory lock PostgreSQL: più repliche worker non duplicano il lavoro.</p><p>Le migrazioni dello schema le applicano solo i processi <code>api</code> e <code>all</code>, all&#39;avvio e una replica alla volta (advisory lock di sessione PostgreSQL: le altre repliche attendono fino a 10 minuti e poi trovano lo schema già aggiornato). Il ruolo <code>worker</code> non migra mai: all&#39;avvio verifica la versione dello schema e, finché è più vecchia di quella richiesta dal binario, non esegue alcun job e riprova con backoff (da 1 s fino a 30 s, con un warning <code>waiting for the API to migrate the database schema</code> nei log); in quella fase <code>/healthz</code> risponde 200 e <code>/readyz</code> 503. Uno schema più recente (rolling upgrade con l&#39;API già aggiornata) è accettato.</p><h2 id="variabili" tabindex="-1">Variabili <a class="header-anchor" href="#variabili" aria-label="Permalink to &quot;Variabili&quot;">​</a></h2><p>Le colonne &quot;Obbl.&quot; indicano se il servizio rifiuta di avviarsi senza la variabile (o senza una delle alternative indicate).</p><p>Un valore che non si interpreta non viene mai sostituito in silenzio dal default: una durata senza unità (<code>SHUTDOWN_TIMEOUT=30</code> invece di <code>30s</code>) o un booleano non riconosciuto (<code>S3_USE_PATH_STYLE=yes</code>; valori ammessi <code>true</code>/<code>false</code>, <code>1</code>/<code>0</code>) fanno fallire l&#39;avvio con un errore che elenca tutte le variabili sbagliate. Sono rifiutati anche <code>SHUTDOWN_TIMEOUT</code> non positivo, <code>SHUTDOWN_DRAIN</code> negativo e <code>OIDC_STATUS_CACHE_TTL</code> fuori dall&#39;intervallo 0–5m (0 disattiva la cache).</p><h3 id="rete-e-processo" tabindex="-1">Rete e processo <a class="header-anchor" href="#rete-e-processo" aria-label="Permalink to &quot;Rete e processo&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variabile</th><th>Default</th><th>Obbl.</th><th>Descrizione</th></tr></thead><tbody><tr><td><code>LISTEN_ADDR</code></td><td><code>127.0.0.1:18081</code></td><td>no</td><td>Indirizzo HTTP (API REST <code>/api/v1</code>, Web UI, <code>/metrics</code>). L&#39;immagine Docker imposta <code>0.0.0.0:18081</code>.</td></tr><tr><td><code>GRPC_LISTEN_ADDR</code></td><td><code>127.0.0.1:18082</code></td><td>no</td><td>Indirizzo gRPC dello stream di notifiche. L&#39;immagine imposta <code>0.0.0.0:18082</code>.</td></tr><tr><td><code>METRICS_LISTEN_ADDR</code></td><td><code>127.0.0.1:18083</code></td><td>no</td><td>Solo <code>--role=worker</code>: listener interno con <code>/metrics</code> (metriche dei job per Prometheus), <code>/healthz</code> (liveness: lo scheduler dei job è attivo, oppure attende la migrazione dello schema) e <code>/readyz</code> (readiness: i job girano). L&#39;immagine imposta <code>0.0.0.0:18083</code>. Non va esposto pubblicamente. Nei ruoli <code>api</code> e <code>all</code> gli stessi endpoint sono su <code>LISTEN_ADDR</code>.</td></tr><tr><td><code>PUBLIC_GRPC_ADDR</code></td><td>= <code>GRPC_LISTEN_ADDR</code></td><td>no</td><td><code>host:porta</code> con cui i client raggiungono lo stream (dietro ingress differisce dall&#39;indirizzo di ascolto); esposto da <code>GET /client-config</code>.</td></tr><tr><td><code>WEB_UI_ORIGIN</code></td><td>vuoto</td><td>no</td><td>Origine del Web UI ammessa da CORS (es. <code>https://clarae.example.com</code>). Vuoto = CORS disattivato.</td></tr><tr><td><code>TRUSTED_PROXIES</code></td><td>vuoto</td><td>no</td><td>Elenco separato da virgole di reti CIDR o indirizzi dei reverse proxy/ingress di cui si accetta <code>X-Forwarded-For</code> per ricavare l&#39;IP del client (limite di richieste per IP). Vuoto = l&#39;IP è quello della connessione TCP: dietro un proxy tutti gli utenti condividerebbero un unico limite (all&#39;avvio il servizio lo segnala con un warning). Il chart Helm e il compose on-premise impostano già le reti private.</td></tr><tr><td><code>LOG_LEVEL</code></td><td><code>info</code></td><td>no</td><td><code>debug</code>, <code>info</code>, <code>warn</code>, <code>error</code> (log JSON su stdout).</td></tr><tr><td><code>SHUTDOWN_TIMEOUT</code></td><td><code>15s</code></td><td>no</td><td>Durata massima dello spegnimento ordinato (formato Go: <code>30s</code>, <code>1m</code>).</td></tr><tr><td><code>SHUTDOWN_DRAIN</code></td><td><code>5s</code></td><td>no</td><td>Quanto il servizio resta in ascolto dopo SIGTERM con <code>/readyz</code> già non pronto, così il bilanciatore smette di inviare traffico prima dello spegnimento; <code>api.preStopSleepSeconds</code> + <code>SHUTDOWN_DRAIN</code> + <code>SHUTDOWN_TIMEOUT</code> deve stare sotto <code>terminationGracePeriodSeconds</code>. Durante il drain restano aperti anche gli stream gRPC e SSE.</td></tr></tbody></table><h3 id="database" tabindex="-1">Database <a class="header-anchor" href="#database" aria-label="Permalink to &quot;Database&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variabile</th><th>Default</th><th>Obbl.</th><th>Descrizione</th></tr></thead><tbody><tr><td><code>DATABASE_URL</code></td><td>—</td><td><strong>sì</strong></td><td>URL PostgreSQL (<code>postgres://utente:password@host:5432/db?sslmode=require</code>). Le migrazioni si applicano all&#39;avvio dei ruoli <code>api</code>/<code>all</code> (vedi <a href="#ruolo-del-processo">Ruolo del processo</a>). La dimensione del pool di connessioni si imposta con il parametro <code>pool_max_conns</code> dell&#39;URL (es. <code>...&amp;pool_max_conns=20</code>); senza, vale il default di pgx (il maggiore tra 4 e il numero di CPU) con un minimo di 8. I job del ruolo <code>worker</code> tengono i propri lock su un pool separato di una connessione per job (5 al massimo), da aggiungere al conto delle connessioni verso PostgreSQL.</td></tr><tr><td><code>DB_EXPECT_INITIALIZED</code></td><td><code>false</code></td><td>no</td><td><code>true</code> dichiara che il database esiste già: i ruoli <code>api</code>/<code>all</code> che lo trovano vuoto (nessuna migrazione applicata) <strong>non creano lo schema</strong> e terminano con un errore, invece di avviarsi su un database nuovo senza dati né registro di audit. Il chart Helm lo imposta da solo a ogni <code>helm upgrade</code> (<code>.Release.IsUpgrade</code>), a meno che <code>config</code> non lo contenga già (<code>&#39;false&#39;</code> lo spegne, per un nuovo tentativo di una prima installazione fallita). Con Compose si imposta in <code>.env</code> (<code>DB_EXPECT_INITIALIZED=true</code>, dopo il primo avvio; il file Compose lo inoltra), insieme a <code>COMPOSE_PROJECT_NAME</code>, senza default. Lasciarlo spento solo per una prima installazione voluta. Vedi <a href="./backup-upgrade.html#aggiornare-senza-perdere-il-database">Backup, ripristino e upgrade</a>.</td></tr></tbody></table><p>All&#39;avvio dei ruoli <code>api</code>/<code>all</code>, dopo le migrazioni, il servizio scrive nel log una riga <code>database state</code> con la versione dello schema (<code>schema_version</code>, <code>schema_expected</code>), il numero di righe del registro di audit (<code>audit_rows</code>) e la data della prima (<code>audit_first_at</code>). La riga più vecchia del registro non avanza mai: dopo un aggiornamento, una <code>audit_first_at</code> che coincide con il giorno dell&#39;aggiornamento, o <code>audit_rows</code> a zero su un&#39;installazione in uso, indica che il database è stato ricreato.</p><h3 id="nomi-di-default-la-famiglia-dell-issuer" tabindex="-1">Nomi di default: la famiglia dell&#39;issuer <a class="header-anchor" href="#nomi-di-default-la-famiglia-dell-issuer" aria-label="Permalink to &quot;Nomi di default: la famiglia dell&#39;issuer&quot;">​</a></h3><p>Le installazioni create prima della 1.5 hanno un realm <code>memobrain</code>, con i client, l&#39;audience e i bucket che portano il vecchio nome. Per non rompere né i client 1.4.0 né i blob già archiviati, i default che contengono il nome del prodotto <strong>seguono l&#39;issuer</strong>: se <code>OIDC_ISSUER</code> termina con <code>/realms/memobrain</code> valgono i nomi della 1.x (<code>memobrain-api</code>, <code>memobrain-desktop</code>, <code>memobrain-web</code>, <code>memobrain-admin-svc</code>, <code>memobrain-blobs</code>, <code>memobrain-exports</code>, namespace delle metriche <code>memobrain</code>), per qualunque altro issuer quelli nuovi (<code>clarae-…</code>). Il default di <code>KC_REALM</code> è il realm indicato dall&#39;issuer. Una variabile impostata esplicitamente vince sempre. All&#39;avvio un realm della 1.x viene segnalato con un warning; i nomi della 1.x sono supportati fino alla 2.0 (vedi <a href="./migrazione-clarae.html">migrazione a Clarae notanda</a>).</p><p>Il ruolo <code>worker</code> non richiede <code>OIDC_ISSUER</code>, ma senza di esso i default sono quelli nuovi: su un&#39;installazione della 1.x passargli lo stesso <code>OIDC_ISSUER</code> dell&#39;API (o i nomi dei bucket espliciti).</p><h3 id="archivio-oggetti-blob-ed-export" tabindex="-1">Archivio oggetti (blob ed export) <a class="header-anchor" href="#archivio-oggetti-blob-ed-export" aria-label="Permalink to &quot;Archivio oggetti (blob ed export)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variabile</th><th>Default</th><th>Obbl.</th><th>Descrizione</th></tr></thead><tbody><tr><td><code>S3_ENDPOINT</code></td><td>vuoto</td><td>sì, o <code>STORAGE_DIR</code></td><td>Endpoint S3-compatibile (RustFS, MinIO, AWS S3, Ceph…).</td></tr><tr><td><code>S3_ACCESS_KEY</code></td><td>vuoto</td><td>con S3</td><td>Access key (segreto: usare un Secret).</td></tr><tr><td><code>S3_SECRET_KEY</code></td><td>vuoto</td><td>con S3</td><td>Secret key (segreto).</td></tr><tr><td><code>S3_REGION</code></td><td><code>us-east-1</code></td><td>no</td><td>Regione S3.</td></tr><tr><td><code>S3_BUCKET_BLOBS</code></td><td><code>clarae-blobs</code> (<code>memobrain-blobs</code> con il realm <code>memobrain</code>)</td><td>no</td><td>Bucket dei blob content-addressed. Se manca viene creato, <strong>tranne</strong> quando il nome è il default, non esiste e esiste il bucket della 1.x (<code>memobrain-blobs</code>): il servizio rifiuta di partire e nomina la variabile da impostare, perché un bucket nuovo e vuoto farebbe risultare mancanti tutti i blob.</td></tr><tr><td><code>S3_BUCKET_EXPORTS</code></td><td><code>clarae-exports</code> (<code>memobrain-exports</code> con il realm <code>memobrain</code>)</td><td>no</td><td>Bucket degli archivi ZIP di export. Stessa regola di <code>S3_BUCKET_BLOBS</code>.</td></tr><tr><td><code>S3_USE_PATH_STYLE</code></td><td><code>true</code></td><td>no</td><td><code>true</code> per MinIO/RustFS (path-style), <code>false</code> per AWS S3 con virtual-host.</td></tr><tr><td><code>S3_PUBLIC_ENDPOINT</code></td><td>vuoto</td><td>no</td><td>Endpoint raggiungibile dai browser: se impostato i download di export usano URL presigned (il bucket richiede una regola CORS per l&#39;origine del Web UI); vuoto = scaricati tramite l&#39;API (ADR-0012).</td></tr><tr><td><code>STORAGE_DIR</code></td><td>vuoto</td><td>alternativa a S3</td><td>Directory locale per i blob quando <code>S3_ENDPOINT</code> è vuoto. Solo sviluppo/test a nodo singolo.</td></tr></tbody></table><h3 id="autenticazione-oidc-keycloak" tabindex="-1">Autenticazione (OIDC / Keycloak) <a class="header-anchor" href="#autenticazione-oidc-keycloak" aria-label="Permalink to &quot;Autenticazione (OIDC / Keycloak)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variabile</th><th>Default</th><th>Obbl.</th><th>Descrizione</th></tr></thead><tbody><tr><td><code>OIDC_ISSUER</code></td><td>—</td><td>sì (non-worker)</td><td>URL dell&#39;issuer del realm (<code>https://auth.example.com/realms/clarae</code>). Usato per JWKS e claim <code>iss</code>.</td></tr><tr><td><code>OIDC_AUDIENCE</code></td><td><code>clarae-api</code> (<code>memobrain-api</code> con il realm <code>memobrain</code>)</td><td>sì (non-worker)</td><td>Valore atteso del claim <code>aud</code>.</td></tr><tr><td><code>OIDC_ALLOWED_AZP</code></td><td><code>clarae-desktop,clarae-web</code> (<code>memobrain-desktop,memobrain-web</code>)</td><td>no</td><td>Client id (claim <code>azp</code>) ammessi a chiamare l&#39;API, separati da virgola.</td></tr><tr><td><code>OIDC_ADMIN_ROLES</code></td><td><code>clarae-admin,memobrain-admin</code></td><td>no</td><td>Ruoli del realm che rendono un utente amministratore (basta uno). Il secondo è il ruolo della 1.x: il default accetta entrambi, così un realm esistente funziona senza modifiche. Alla creazione o promozione di un utente dalla console viene assegnato il primo ruolo della lista presente nel realm; la revoca toglie tutti quelli posseduti.</td></tr><tr><td><code>OIDC_DESKTOP_CLIENT_ID</code></td><td><code>clarae-desktop</code> (<code>memobrain-desktop</code>)</td><td>no</td><td>Client pubblico del desktop, pubblicato da <code>GET /client-config</code>.</td></tr><tr><td><code>OIDC_WEB_CLIENT_ID</code></td><td><code>clarae-web</code> (<code>memobrain-web</code>)</td><td>no</td><td>Client pubblico del Web UI, pubblicato da <code>GET /client-config</code>.</td></tr><tr><td><code>OIDC_STATUS_CACHE_TTL</code></td><td><code>30s</code></td><td>no</td><td>Per quanto il servizio memorizza lo stato di un utente (sospensione): è il ritardo massimo con cui una sospensione blocca un token ancora valido.</td></tr></tbody></table><h3 id="keycloak-admin-rest-service-account" tabindex="-1">Keycloak Admin REST (service account) <a class="header-anchor" href="#keycloak-admin-rest-service-account" aria-label="Permalink to &quot;Keycloak Admin REST (service account)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variabile</th><th>Default</th><th>Obbl.</th><th>Descrizione</th></tr></thead><tbody><tr><td><code>KC_ADMIN_BASE_URL</code></td><td>vuoto</td><td>per la console admin</td><td>URL base di Keycloak (senza <code>/realms/...</code>). Vuoto = le operazioni admin sugli utenti non funzionano.</td></tr><tr><td><code>KC_REALM</code></td><td>il realm di <code>OIDC_ISSUER</code> (<code>clarae</code> se l&#39;issuer non ne ha uno)</td><td>no</td><td>Nome del realm.</td></tr><tr><td><code>KC_ADMIN_CLIENT_ID</code></td><td><code>clarae-admin-svc</code> (<code>memobrain-admin-svc</code> con il realm <code>memobrain</code>)</td><td>no</td><td>Client confidential con service account (ruoli minimi: vedi <a href="./keycloak.html">Keycloak</a>).</td></tr><tr><td><code>KC_ADMIN_CLIENT_SECRET</code></td><td>vuoto</td><td>per la console admin</td><td>Segreto del client (segreto: usare un Secret).</td></tr></tbody></table><h3 id="segreti-segnaposto" tabindex="-1">Segreti segnaposto <a class="header-anchor" href="#segreti-segnaposto" aria-label="Permalink to &quot;Segreti segnaposto&quot;">​</a></h3><p>All&#39;avvio il servizio rifiuta di partire se un segreto vale ancora uno dei segnaposto dei modelli di installazione (<code>change-me</code>, <code>change-me-too</code>, <code>changeme</code>, senza distinzione di maiuscole): la password di <code>DATABASE_URL</code>, <code>S3_ACCESS_KEY</code>, <code>S3_SECRET_KEY</code>, <code>KC_ADMIN_CLIENT_SECRET</code>. Il compose on-premise fa lo stesso controllo, prima di avviare PostgreSQL, S3 e Keycloak, anche su <code>KEYCLOAK_DB_PASSWORD</code> e <code>KC_BOOTSTRAP_ADMIN_PASSWORD</code> (servizio <code>preflight</code>); il chart Helm non crea il Secret con valori vuoti o segnaposto.</p><table tabindex="0"><thead><tr><th>Variabile</th><th>Default</th><th>Obbl.</th><th>Descrizione</th></tr></thead><tbody><tr><td><code>CLARAE_ALLOW_PLACEHOLDER_SECRETS</code></td><td><code>false</code></td><td>no</td><td><code>1</code>/<code>true</code> disattiva il controllo (servizio e <code>preflight</code> del compose). Solo per prove usa e getta: <strong>mai in produzione</strong>. Il nome della 1.x <code>MEMOBRAIN_ALLOW_PLACEHOLDER_SECRETS</code> vale ancora se il nuovo non è impostato, con un warning all&#39;avvio (rimosso nella 2.0).</td></tr></tbody></table><h3 id="metriche" tabindex="-1">Metriche <a class="header-anchor" href="#metriche" aria-label="Permalink to &quot;Metriche&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variabile</th><th>Default</th><th>Obbl.</th><th>Descrizione</th></tr></thead><tbody><tr><td><code>METRICS_NAMESPACE</code></td><td><code>clarae</code> (<code>memobrain</code> con il realm <code>memobrain</code>)</td><td>no</td><td>Prefisso delle metriche Prometheus del servizio (<code>&lt;namespace&gt;_http_requests_total</code>, …). Ammesse lettere minuscole, cifre e <code>_</code>, senza cifra iniziale: un valore non valido fa fallire l&#39;avvio. Un&#39;installazione della 1.x mantiene <code>memobrain</code> per non spezzare dashboard e alert esistenti; per passare a <code>clarae</code> impostare <code>clarae</code> e reimportare dashboard e alert.</td></tr></tbody></table><h2 id="impostazioni-a-runtime-non-sono-variabili-d-ambiente" tabindex="-1">Impostazioni a runtime (non sono variabili d&#39;ambiente) <a class="header-anchor" href="#impostazioni-a-runtime-non-sono-variabili-d-ambiente" aria-label="Permalink to &quot;Impostazioni a runtime (non sono variabili d&#39;ambiente)&quot;">​</a></h2><p>Alcuni parametri si cambiano dalla console admin (<strong>Limiti</strong>) o dalla tabella <code>settings</code> senza riavviare il servizio. Valori predefiniti:</p><table tabindex="0"><thead><tr><th>Chiave</th><th>Default</th><th>Significato</th></tr></thead><tbody><tr><td><code>files.max_size_bytes</code></td><td>100 MiB</td><td>Dimensione massima di un file sincronizzato.</td></tr><tr><td><code>history.retention_days</code></td><td>30</td><td>Giorni in cui si conservano tutte le revisioni.</td></tr><tr><td><code>history.daily_retention_days</code></td><td>90</td><td>Giorni in cui si conserva una revisione al giorno (poi viene potata).</td></tr><tr><td><code>sync.changelog_window_days</code></td><td>90</td><td>Oltre questa finestra i client molto indietro ripartono dal manifesto.</td></tr><tr><td><code>vaults.deleted_retention_days</code></td><td>30</td><td>Periodo in cui un vault eliminato è ancora recuperabile prima del purge.</td></tr><tr><td><code>blobs.gc_grace_hours</code></td><td>24</td><td>Attesa prima di cancellare un blob non più referenziato.</td></tr><tr><td><code>uploads.expiry_hours</code></td><td>24</td><td>Durata di un upload riprendibile (tus) e finestra in cui un blob caricato ma non ancora committato conta nella quota del proprietario.</td></tr><tr><td><code>exports.workers</code></td><td>2</td><td>Archivi ZIP di export costruiti in parallelo dal worker (massimo 16).</td></tr><tr><td><code>exports.max_active_per_user</code></td><td>3</td><td>Job di export in coda o in esecuzione per utente; oltre, <code>429 RATE_LIMITED</code>. Un vault ha al più un job attivo: una nuova richiesta restituisce quello.</td></tr></tbody></table><p><strong>Export.</strong> <code>exports.max_active_per_user</code> limita anche gli export ZIP in streaming diretto (<code>GET /vaults/{id}/export.zip</code>) aperti contemporaneamente da un utente su ciascun nodo API. Una nuova richiesta di export su un vault che non è cambiato dall&#39;ultimo archivio pronto (ancora scaricabile per almeno un&#39;ora) restituisce quell&#39;archivio invece di costruirne una copia; quando un nuovo archivio è pronto, i precedenti dello stesso vault restano scaricabili al più per un&#39;altra ora. Un job il cui vault o account viene eliminato termina <code>failed</code> e il suo archivio non viene conservato; un job interrotto dall&#39;arresto del worker torna in coda.</p><p><strong>Quota e upload.</strong> La quota conta solo i file correnti (D-03), addebitati al commit. I byte caricati ma non ancora committati (blob caricati entro <code>uploads.expiry_hours</code> che nessuna revisione referenzia, più la lunghezza annunciata degli upload tus in corso) non compaiono in <code>used_bytes</code> ma limitano i nuovi upload: un upload che non sta nella quota insieme ai byte usati e a quelli in attesa è rifiutato con <code>413 QUOTA_EXCEEDED</code>. Conviene tenere <code>blobs.gc_grace_hours</code> non superiore a <code>uploads.expiry_hours</code>: un blob mai committato smette di contare alla fine della finestra e occupa spazio finché il GC non lo rimuove.</p><p>La quota predefinita e le soglie di avviso/critica (<code>warn_percent</code>, <code>critical_percent</code>) si impostano nella stessa pagina <strong>Limiti</strong>.</p><h2 id="esempi" tabindex="-1">Esempi <a class="header-anchor" href="#esempi" aria-label="Permalink to &quot;Esempi&quot;">​</a></h2><p>Sviluppo (<code>deploy/docker/cloud.dev.env</code>) e Kubernetes (<code>deploy/helm/clarae/values.yaml</code>, sezioni <code>config:</code> per le variabili non segrete e <code>secret:</code> per <code>DATABASE_URL</code>, <code>S3_ACCESS_KEY</code>, <code>S3_SECRET_KEY</code>, <code>KC_ADMIN_CLIENT_SECRET</code>).</p>',36)])])}const h=o(i,[["render",c]]);export{p as __pageData,h as default};
